<script lang="ts">
  // Interactive topology view. The document comes from the Rust projection
  // (mock: committed goldens generated BY that projection) — this component
  // renders it; it never derives relationships itself.

  import cytoscape from 'cytoscape';
  import type { NodeId, TopologyDocument, TopologyNode } from '../types';
  import { nodeIdKey } from '../lib/topology';
  import MockBadge from './MockBadge.svelte';

  let {
    document,
    highlight = [],
    onselect,
  }: {
    document: TopologyDocument;
    highlight?: NodeId[];
    onselect?: (node: TopologyNode) => void;
  } = $props();

  let container = $state<HTMLDivElement>();
  let cy: cytoscape.Core | null = null;

  // Test/inspection hook (read-only counts + deterministic selection,
  // which invokes exactly the same callback as a canvas click). Exposed
  // ONLY in development or when the page is explicitly opened with the
  // ?araiguma-test-hooks parameter (used by the e2e suite against the
  // production build) — a normal visitor of the production build never
  // gets test instrumentation on window. The global is removed when the
  // component is destroyed, so no stale reference outlives the view.
  const TEST_HOOK_PARAM = 'araiguma-test-hooks';
  const testHooksEnabled =
    import.meta.env.DEV ||
    (typeof window !== 'undefined' &&
      new URLSearchParams(window.location.search).has(TEST_HOOK_PARAM));

  // Convert the document to cytoscape elements.
  function elements(doc: TopologyDocument): cytoscape.ElementDefinition[] {
    const nodes: cytoscape.ElementDefinition[] = doc.nodes.map((node) => ({
      group: 'nodes',
      data: {
        id: nodeIdKey(node.id),
        label: node.label,
        kind: node.nodeKind,
        state: node.state,
        interfaceKind: node.interfaceKind ?? '',
      },
    }));
    const edges: cytoscape.ElementDefinition[] = doc.edges.map((edge, index) => ({
      group: 'edges',
      data: {
        id: `edge-${index}`,
        source: nodeIdKey(edge.from),
        target: nodeIdKey(edge.to),
        kind: edge.edgeKind,
        inferred: 'inferred' in edge.evidence,
      },
    }));
    return [...nodes, ...edges];
  }

  const cytoscapeStyle: cytoscape.StylesheetJson = [
    {
      selector: 'node',
      style: {
        label: 'data(label)',
        'text-valign': 'bottom',
        'text-margin-y': 6,
        'font-family': 'var(--font-mono), monospace',
        'font-size': 11,
        color: '#9aa2b1',
        width: 34,
        height: 34,
        'border-width': 2,
      },
    },
    {
      selector: 'node[kind = "interface"][state = "active"]',
      style: { 'background-color': '#1d3a2f', 'border-color': '#52c58f' },
    },
    {
      selector: 'node[kind = "interface"][state = "inactive"]',
      style: { 'background-color': '#22161a', 'border-color': '#d07676' },
    },
    {
      selector: 'node[kind = "interface"][state = "unknown"]',
      style: { 'background-color': '#2c2618', 'border-color': '#c9a44d' },
    },
    {
      selector: 'node[kind = "gateway"]',
      style: {
        shape: 'diamond',
        'background-color': '#16232e',
        'border-color': '#4cc9e8',
        width: 26,
        height: 26,
      },
    },
    {
      selector: 'edge',
      style: {
        width: 2,
        'line-color': '#303748',
        'target-arrow-color': '#303748',
        'target-arrow-shape': 'triangle',
        'curve-style': 'bezier',
        'arrow-scale': 0.8,
      },
    },
    {
      selector: 'edge[inferred = true]',
      style: { 'line-style': 'dashed', 'line-color': '#3c5a74', 'target-arrow-color': '#3c5a74' },
    },
    {
      selector:
        'edge[kind = "bridgeMember"], edge[kind = "bondMember"], edge[kind = "masterMember"], edge[kind = "linkParent"]',
      style: { 'line-color': '#41507a', 'target-arrow-color': '#41507a' },
    },
    {
      selector: '.highlighted',
      style: {
        'border-width': 4,
        'border-color': '#e8eaef',
        'line-color': '#e8eaef',
        'target-arrow-color': '#e8eaef',
        width: 3,
      },
    },
  ];

  $effect(() => {
    // (Re)build the graph whenever the document identity changes.
    void document;
    cy?.destroy();
    cy = cytoscape({
      container,
      elements: elements(document),
      style: cytoscapeStyle,
      layout: {
        name: 'cose',
        animate: false,
        nodeRepulsion: 9000,
        padding: 30,
      },
      wheelSensitivity: 0.2,
    });
    cy.on('tap', 'node', (event) => {
      const id = event.target.id();
      const node = document.nodes.find((n) => nodeIdKey(n.id) === id);
      if (node && onselect) onselect(node);
    });
    // Test/inspection hook — see testHooksEnabled above.
    if (testHooksEnabled) {
      (window as unknown as Record<string, unknown>).__araigumaTopology = {
        nodeCount: document.nodes.length,
        edgeCount: document.edges.length,
        nodeLabels: document.nodes.map((n) => n.label),
        selectNode: (label: string) => {
          const node = document.nodes.find((n) => n.label === label);
          if (node && onselect) onselect(node);
        },
      };
    }
    return () => {
      cy?.destroy();
      cy = null;
      // Never leave a stale global behind after the component unmounts.
      if (testHooksEnabled) {
        delete (window as unknown as Record<string, unknown>).__araigumaTopology;
      }
    };
  });

  $effect(() => {
    // Highlight the nodes a selected route refers to (linkage from the
    // routes view) — highlight only, nothing is modified.
    void highlight;
    if (!cy) return;
    cy.elements().removeClass('highlighted');
    for (const id of highlight) {
      cy.getElementById(nodeIdKey(id)).addClass('highlighted');
      cy.getElementById(nodeIdKey(id)).connectedEdges().addClass('highlighted');
    }
  });
</script>

<div class="topology-view">
  <header class="view-head">
    <div>
      <h1>Network topology</h1>
      <p class="sub">
        {document.nodes.length} nodes · {document.edges.length} evidenced relations ·
        relationships without evidence are not drawn
      </p>
    </div>
    <MockBadge />
  </header>

  {#if document.nodes.length === 0}
    <div class="empty-state" data-testid="topology-empty">
      <p>No observed interfaces — the topology is legitimately empty.</p>
      <p class="sub">
        This is a valid observation of an empty environment, not an error.
      </p>
    </div>
  {:else}
    <div class="canvas-wrap">
      <div class="canvas" bind:this={container} data-testid="topology-canvas"></div>
      <aside class="legend" aria-label="Topology legend">
        <div class="legend-group">
          <span class="swatch gateway"></span> gateway (routing fact)
        </div>
        <div class="legend-group">
          <span class="swatch active"></span> interface up
        </div>
        <div class="legend-group">
          <span class="swatch inactive"></span> interface down
        </div>
        <div class="legend-group">
          <span class="swatch unknown"></span> state unknown
        </div>
        <div class="legend-group">
          <span class="line"></span> observed relation
        </div>
        <div class="legend-group">
          <span class="line dashed"></span> inferred relation
        </div>
        <p class="legend-note">
          Gateways exist only where a route names them. Anything beyond a
          gateway — upstream or internet — is not observed and not drawn.
        </p>
      </aside>
    </div>
  {/if}
</div>

<style>
  .topology-view {
    display: flex;
    flex-direction: column;
    height: 100%;
    padding: 22px 26px 26px;
  }

  .view-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
  }

  h1 {
    margin: 0;
    font-size: 19px;
    font-weight: 600;
  }

  .sub {
    margin: 4px 0 0;
    color: var(--text-secondary);
    font-size: 12.5px;
  }

  .canvas-wrap {
    position: relative;
    flex: 1;
    min-height: 0;
    margin-top: 16px;
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-m);
    background: var(--bg-inset);
    overflow: hidden;
  }

  .canvas {
    position: absolute;
    inset: 0;
  }

  .legend {
    position: absolute;
    right: 12px;
    bottom: 12px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 10px 12px;
    background: color-mix(in srgb, var(--bg-panel) 92%, transparent);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-s);
    font-size: 11.5px;
    color: var(--text-secondary);
    max-width: 260px;
  }

  .legend-group {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .swatch {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2px solid;
    flex: none;
  }

  .swatch.gateway {
    border-radius: 2px;
    transform: rotate(45deg) scale(0.9);
    border-color: #4cc9e8;
    background: #16232e;
  }

  .swatch.active {
    border-color: #52c58f;
    background: #1d3a2f;
  }

  .swatch.inactive {
    border-color: #d07676;
    background: #22161a;
  }

  .swatch.unknown {
    border-color: #c9a44d;
    background: #2c2618;
  }

  .line {
    width: 18px;
    height: 0;
    border-top: 2px solid #303748;
    flex: none;
  }

  .line.dashed {
    border-top-style: dashed;
    border-top-color: #3c5a74;
  }

  .legend-note {
    margin: 6px 0 0;
    color: var(--text-muted);
    font-size: 10.5px;
  }

  .empty-state {
    border: 1px dashed var(--border-strong);
    border-radius: var(--radius-m);
    padding: 28px;
    text-align: center;
    margin-top: 16px;
  }

  .empty-state p {
    margin: 0 0 6px;
  }
</style>
